using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BMImport {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B2/",P=A+"Props/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_FullFloor/";
 static Material Save(Material m,string folder){var p=folder+m.name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(p);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,p);m.enableInstancing=true;AssetDatabase.SaveAssetIfDirty(m);return m;}
 public static object Run(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));mats["B2M_Plate"]=mats["B4O_Plate"];mats["B2M_RedLamp"]=mats["B4O_RedLamp"];
 foreach(var file in Directory.GetFiles(E+"Textures","BM_*.png").Concat(Directory.GetFiles(P+"Textures","B2_EmergencyGenerator*.png"))){string p=file.Replace('\\','/');var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.maxTextureSize=p.Contains("Generator")?2048:1024;ti.sRGBTexture=!p.Contains("MetalSmooth")&&!p.EndsWith("_0_1.png")&&!p.EndsWith("_0_3.png");if(p.EndsWith("_0_2.png")){ti.textureType=TextureImporterType.NormalMap;ti.sRGBTexture=false;}ti.alphaIsTransparency=p.Contains("Guide");ti.wrapMode=p.Contains("Display")||p.Contains("Guide")?TextureWrapMode.Clamp:TextureWrapMode.Repeat;ti.anisoLevel=8;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();}
 foreach(string n in new[]{"Pipe","PipeRed"}){var m=new Material(mats["B4O_Steel"]){name="BM_"+n};m.SetColor("_BaseColor",n=="Pipe"?new Color(.46f,.51f,.55f):new Color(.30f,.08f,.055f));m.SetFloat("_Metallic",.8f);m.SetFloat("_Smoothness",.75f);mats[m.name]=Save(m,E+"Materials/");}
 foreach(int i in new[]{11,12,13,14,15,16,22}){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BM_Display_"+i.ToString("00")};m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+m.name+".png"));m.SetFloat("_Smoothness",.2f);mats["B4O_Display_"+i.ToString("00")]=Save(m,E+"Materials/");}
 var gm=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="B2_EmergencyGenerator_PBR_0"};gm.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/B2_EmergencyGenerator_0_0.png"));gm.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/B2_EmergencyGenerator_0_2.png"));gm.EnableKeyword("_NORMALMAP");gm.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/B2_EmergencyGenerator_MetalSmooth.png"));gm.EnableKeyword("_METALLICSPECGLOSSMAP");gm.SetFloat("_Smoothness",1);mats[gm.name]=Save(gm,P+"Materials/");
 var colors=JObject.Parse(File.ReadAllText(H+"guide_colors.json"));foreach(var kv in colors){Color col;ColorUtility.TryParseHtmlString("#"+(string)kv.Value["hex"],out col);var line=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BM_Line_"+kv.Key};line.SetColor("_BaseColor",col);line.SetFloat("_Smoothness",.15f);line=Save(line,E+"Materials/");var label=new Material(line){name="BM_Guide_"+kv.Key};label.SetColor("_BaseColor",Color.white);label.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+label.name+".png"));label.SetFloat("_AlphaClip",1);label.SetFloat("_Cutoff",.3f);label.EnableKeyword("_ALPHATEST_ON");label.renderQueue=2450;Save(label,E+"Materials/");}
 int count=0;foreach(string p in Directory.GetFiles(E,"BM_*.fbx").Concat(Directory.GetFiles(P,"BM_*.fbx")).Append(P+"B2_EmergencyGenerator.fbx").Select(p=>p.Replace('\\','/'))){AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(p);if(mi==null)throw new Exception("Not imported: "+p);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();count++;}return new{models=count,materials=mats.Count};}
 public static object Catalog(){var list=new List<object>();foreach(var p in AssetDatabase.FindAssets("t:Model",new[]{A+"Props"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.EndsWith(".fbx"))){var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);var rs=g.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var bb=rs[0].bounds;foreach(var rr in rs.Skip(1))bb.Encapsulate(rr.bounds);list.Add(new{name=Path.GetFileNameWithoutExtension(p),asset=p,size=new[]{bb.size.x,bb.size.y,bb.size.z},center=new[]{bb.center.x,bb.center.y,bb.center.z}});}File.WriteAllText(H+"catalog.json",JsonConvert.SerializeObject(list,Formatting.Indented));return new{models=list.Count};}
}
